/* ═══ SOUND SYSTEM (Web Audio API) ═══ */
const SND = {
  _ctx: null,
  _get() { if(!this._ctx) this._ctx = new (window.AudioContext || window.webkitAudioContext)(); return this._ctx; },
  _play(freq, dur, type="sine", vol=0.15) {
    try {
      const ctx=this._get(), o=ctx.createOscillator(), g=ctx.createGain();
      o.type=type; o.frequency.value=freq;
      g.gain.setValueAtTime(vol,ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+dur);
      o.connect(g); g.connect(ctx.destination);
      o.start(ctx.currentTime); o.stop(ctx.currentTime+dur);
    } catch {}
  },
  login() { this._play(523,.15); setTimeout(()=>this._play(659,.15),150); setTimeout(()=>this._play(784,.3),300); },
  error() { this._play(200,.15,"square",0.1); setTimeout(()=>this._play(160,.25,"square",0.1),150); },
  notify() { this._play(880,.1); setTimeout(()=>this._play(1100,.15),120); },
  click() { this._play(1200,.05,"sine",0.05); },
  send() { this._play(600,.08); setTimeout(()=>this._play(800,.12),80); },
  open() { this._play(400,.08); setTimeout(()=>this._play(500,.1),60); },
  close() { this._play(500,.06); setTimeout(()=>this._play(350,.1),60); },
};

/* ═══ Storage (shared=true for sync) ═══ */
async function LD(k,fb,sh=false){try{const r=await window.storage.get(k,sh);return r?JSON.parse(r.value):fb;}catch{return fb;}}
async function SV(k,v,sh=false){try{await window.storage.set(k,JSON.stringify(v),sh);}catch{}}
async function initDefaults(){const u=await LD("w-users",null,true);if(!u){await SV("w-users",[DEFAULT_OWNER],true);return[DEFAULT_OWNER];}return u;}

