/* ═══════════════════════════════════
   SYNCED APPS (shared=true)
   All data synced across users every 2s
   ═══════════════════════════════════ */

function useSyncedData(key, fallback, interval=2000) {
  const [data, setData] = useState(fallback);
  useEffect(() => {
    const load = () => LD(key, fallback, true).then(setData);
    load();
    const iv = setInterval(load, interval);
    return () => clearInterval(iv);
  }, [key]);
  const save = useCallback((d) => { setData(d); SV(key, d, true); }, [key]);
  return [data, save];
}

